<?php require_once 'config.php';if(!user())go('login.php');$cart=$_SESSION['cart']??[];if(!$cart)go('shop.php');$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE id IN ($in)");$st->execute($ids);$items=$st->fetchAll();$total=0;foreach($items as $p)$total+=$p['price']*$cart[$p['id']];$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO orders(user_id,total,customer_name,phone,address) VALUES(?,?,?,?,?)");$st->execute([user()['id'],$total,$_POST['name'],$_POST['phone'],$_POST['address']]);$oid=$pdo->lastInsertId();$it=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)");foreach($items as $p)$it->execute([$oid,$p['id'],$p['name'],$p['price'],$cart[$p['id']]]);$pdo->commit();unset($_SESSION['cart']);$_SESSION['flash']='Demo order placed successfully.';go('orders.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='Could not place order.';}}$title='Checkout';include 'header.php';?><div class="panel"><h1>Checkout</h1><p class="muted">Demo checkout only. No real payment is collected.</p><?php if($err)echo '<div class="alert alert-danger">'.h($err).'</div>';?><form method="post"><input class="form-control mb-3" name="name" placeholder="Full name" value="<?= h(user()['name']) ?>" required><input class="form-control mb-3" name="phone" placeholder="Phone" required><textarea class="form-control mb-3" name="address" placeholder="Delivery address" required></textarea><p class="price">Total: <?= money($total) ?></p><button class="btn btn-rose">Place demo order</button></form></div><?php include 'footer.php'; ?>
